/**
 * IBM Plex Sans TTFs embedded as base64 for the OG-image route.
 *
 * The worker cannot self-fetch its own asset origin (custom-domain subrequests
 * time out with 522), so the fonts resvg needs are inlined here and decoded at
 * runtime — no network. Regenerate from public/og/*.ttf if the fonts change.
 */

export const IBM_PLEX_REGULAR_B64 = "";
export const IBM_PLEX_SEMIBOLD_B64 = "";

export function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
